import{c as t,Q as a,j as s,m as i}from"./chunks/framework.BXFC_ndL.js";const g=JSON.parse('{"title":"getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function r(o,e,l,h,p,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;getting started&quot;">​</a></h1><p>There are three ways to start writing ghūl: in the browser, in a GitHub Codespace, or on your own machine.</p><h2 id="in-the-browser" tabindex="-1">in the browser <a class="header-anchor" href="#in-the-browser" aria-label="Permalink to &quot;in the browser&quot;">​</a></h2><p>The <a href="https://playground.ghul.dev" target="_blank" rel="noreferrer">ghūl playground</a> compiles and runs ghūl in your browser, with live errors, completion and hover as you type. There is nothing to install. It is what runs the editable examples on this site, and its own menu offers complete programs to start from.</p><h2 id="in-a-codespace" tabindex="-1">in a Codespace <a class="header-anchor" href="#in-a-codespace" aria-label="Permalink to &quot;in a Codespace&quot;">​</a></h2><p>The <a href="https://github.com/degory/ghul-scratchpad" target="_blank" rel="noreferrer">ghūl scratchpad</a> is a minimal one-file project: open it in a GitHub Codespace and it arrives with the .NET SDK, the compiler and the language extension ready to go. Paste any example from this site into <code class="ghul-inline-plain">main.ghul</code> and <code class="ghul-inline"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> run</span></code>. This needs a GitHub account and nothing else.</p><p>The <a href="https://github.com/degory/ghul-examples" target="_blank" rel="noreferrer">examples repository</a> works the same way, with fuller, runnable examples organised by topic.</p><p>Both repositories are configured as <a href="https://containers.dev" target="_blank" rel="noreferrer">dev containers</a>, so the same ready-made environment also opens in VS Code with the Dev Containers extension, or in any other tool that supports them.</p><h2 id="on-your-own-machine" tabindex="-1">on your own machine <a class="header-anchor" href="#on-your-own-machine" aria-label="Permalink to &quot;on your own machine&quot;">​</a></h2><p>To work locally you need the <a href="https://dotnet.microsoft.com/en-us/download/dotnet/10.0" target="_blank" rel="noreferrer">.NET 10 SDK</a> and an editor, and some ghūl code to start from - clone the scratchpad or the examples repository above, or start a project of your own from the <a href="https://github.com/degory/ghul-repository-template" target="_blank" rel="noreferrer">repository template</a>. The compiler is pinned in each repository as a local .NET tool, so it arrives with the code: <code class="ghul-inline"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> tool</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> restore</span></code> fetches it.</p><p><a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">Visual Studio Code</a> with the <a href="https://marketplace.visualstudio.com/items?itemName=degory.ghul" target="_blank" rel="noreferrer">ghūl language extension</a> gives you errors and warnings as you type, completion, hover, go to definition, rename and formatting. Any editor that can install VS Code extensions gets the same support; other editors can drive the underlying language server directly - see <a href="/tooling.html#other-editors">other editors</a> on the tooling page.</p><p>When you first open a project, the extension restores its NuGet packages, builds it, and starts the compiler in analysis mode, which reads the whole project before it can answer. Even for a small project this takes a few seconds. After that the compiler updates its analysis incrementally as you edit, and hover, completion and diagnostics respond in a few milliseconds even on a large project.</p><p>ghūl reads best in a font with programming ligatures, which draw operators such as <code class="ghul-inline"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">=~</span></code>, <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">=&gt;</span></code> and <code class="ghul-inline"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">|&gt;</span></code> as single glyphs. The code is perfectly readable without them, but for the best experience set the editor font to one that provides them, such as <a href="https://github.com/tonsky/FiraCode" target="_blank" rel="noreferrer">Fira Code</a>, and turn ligatures on:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;editor.fontFamily&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">: </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;Fira Code&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">,</span></span>
<span class="line"><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;editor.fontLigatures&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">: </span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">true</span></span></code></pre></div><h2 id="it-s-all-ordinary-net" tabindex="-1">it&#39;s all ordinary .NET <a class="header-anchor" href="#it-s-all-ordinary-net" aria-label="Permalink to &quot;it&#39;s all ordinary .NET&quot;">​</a></h2><p>A ghūl project is a normal .NET SDK project. In each repository above you&#39;ll find a <code class="ghul-inline-plain">.ghulproj</code> - an MSBuild project file with the usual things in it - and the normal <code class="ghul-inline-plain">dotnet</code> commands work as you&#39;d expect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> build</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> run</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> test</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> pack</span></span></code></pre></div><p>A ghūl project can reference NuGet packages, produce libraries or executables, and be packed and published exactly like a C# project.</p><p>To set up a project from scratch, or for more on the template, see <a href="/tooling.html#creating-a-project">creating a project</a> on the tooling page.</p>`,19)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
